using w3.Domain.Interfaces; using w3.Domain.Models; namespace w3.Domain.Services; public class EnrollmentService(IStudentRepository students, ICourseRepository courses) { public Enrollment RegisterStudentToCourse(int studentId, int courseId) { var student = students.GetById(studentId) ?? throw new InvalidOperationException("Học viên không tồn tại"); var course = courses.GetById(courseId) ?? throw new InvalidOperationException("Khóa học không hợp lệ hoặc đã bị xóa"); var enrollment = new Enrollment { StudentId = studentId, CourseId = courseId, EnrollDate = DateTime.Now, Student = student, Course = course }; student.Enrollments.Add(enrollment); students.Save(student); return enrollment; } }
